package fixture;public class BlockState{public boolean isAir(){return id.equals("minecraft:air");}public String id;public Object block;public int age;public BlockState(String id){this.id=id;}public float hardness=1;public float getDestroySpeed(Object w,Object p){return hardness;}public boolean isCollisionShapeFullBlock(Object w,Object p){return !isAir();}public boolean canSurvive(Object w,Object p){return true;}public Object getBlock(){return block==null?id:block;}}